import XCTest

final class SpaceTapUITests: XCTestCase {
    func testOpenSpaces() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 2)

        var tapped = false
        for id in ["Spaces", "spaces", "Space list", "Space rail", "SpacesButton", "spacesButton"] {
            let b = app.buttons[id]
            if b.exists {
                b.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            for b in app.buttons.allElementsBoundByIndex {
                if b.label.lowercased().contains("space") {
                    b.tap()
                    tapped = true
                    break
                }
            }
        }
        if !tapped {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.064, dy: 0.918)).tap()
        }
        Thread.sleep(forTimeInterval: 2)
    }
}

